//
// _preloader.scss
//

#preloader {
    position: fixed;
    top: 0;
    inset-inline-start: 0;
    width: 100%;
    height: 100%;
    background: var(--#{$prefix}body-bg); /* Slight transparency */
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 9999;
}
